import java.io.FileReader;
import java.io.IOException;

public class ExceptionDemo {
    // Checked exception must be declared in the method signature
    public static String readFirstLine(String path) throws IOException {
        FileReader reader = null;
        try {
            reader = new FileReader(path); // throws IOException (checked)
            int ch = reader.read();        // throws IOException (checked)
            if (ch == -1) {
                throw new IllegalArgumentException("File is empty"); // unchecked
            }
            return String.valueOf((char) ch);
        } finally {
            // finally always runs, even if an exception was thrown
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // log and suppress -- do not mask the original exception
                    System.err.println("Failed to close: " + e.getMessage());
                }
            }
        }
    }

    public static void main(String[] args) {
        try {
            String line = readFirstLine("data.txt");
            System.out.println("First char: " + line);
        } catch (IOException e) {
            // Handle the checked exception declared by readFirstLine
            System.err.println("Could not read file: " + e.getMessage());
        } catch (IllegalArgumentException e) {
            // Handle the unchecked exception thrown inside the method
            System.err.println("Bad input: " + e.getMessage());
        }
    }
}

