import java.io.IOException;
import java.nio.file.*;

public class HierarchyDemo {
    // IOException is checked -> must be declared with throws
    void readConfig(String path) throws IOException {
        Files.readString(Path.of(path));
    }

    void run() {
        try {
            readConfig("app.properties");      // checked
            int x = 10 / 0;                      // ArithmeticException (unchecked)
        } catch (IOException e) {                // Exception subclass
            System.err.println("File problem: " + e.getMessage());
        } catch (ArithmeticException e) {        // RuntimeException subclass
            System.err.println("Math problem: " + e.getMessage());
        }
        // OutOfMemoryError extends Error -> we deliberately never catch it
    }
}
```
*Both branches descend from `Throwable`, but only the checked `IOException` forced the `throws` declaration.*

